// Formatting Utilities - Formatlama Fonksiyonları

lớp Formatting {
    tĩnh hàm currency(amount, currency) {
        nếu (currency == "TRY") {
            trả_về amount + " ₺";
        } nếu_không {
            nếu (currency == "USD") {
                trả_về "$" + amount;
            } nếu_không {
                nếu (currency == "EUR") {
                    trả_về "€" + amount;
                } nếu_không {
                    trả_về amount + " " + currency;
                }
            }
        }
    }

    tĩnh hàm date(date) {
        trả_về date;
    }

    tĩnh hàm phone(phone) {
        // (555) 123-4567 formatı
        trả_về "(" + phone + ")";
    }

    tĩnh hàm number(num) {
        // 1,234,567 formatı
        trả_về num;
    }
}

